def should_send(kind, prefs, hour):
    if kind == "transactional":
        return True
    if not prefs.get("marketing_opt_in", False):
        return False
    s, e = prefs["quiet_start"], prefs["quiet_end"]
    quiet = (s <= hour < e) if s < e else (hour >= s or hour < e)
    return not quiet

